HTTP/1.1 400 Bad Request
Content-Type: application/problem+json

{
  "type": "https://http.codes/400",
  "title": "One or more validation errors occurred.",
  "status": 400,
  "traceId": "|abc123.def456|",
  "errors": {
    "Email": ["The Email field is required."],
    "Age": ["The field Age must be between 18 and 120."]
  }
}

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers();
builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = ctx =>
    {
        ctx.ProblemDetails.Extensions["traceId"] = ctx.HttpContext.TraceIdentifier;
        ctx.ProblemDetails.Extensions["instance"] = ctx.HttpContext.Request.Path;
    };
});

var app = builder.Build();
app.UseExceptionHandler();
app.UseStatusCodePages();
app.MapControllers();
app.Run();

public class ApiErrorResponse
{
    public string CorrelationId { get; set; } = string.Empty;
    public int Status { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Detail { get; set; } = string.Empty;
    public string? Code { get; set; }
    public Dictionary<string, string[]> Errors { get; set; } = new();
    public DateTime Timestamp { get; set; } = DateTime.UtcNow;
}

public static ApiErrorResponse FromModelState(ActionContext context)
{
    var errors = context.ModelState
        .Where(kvp => kvp.Value?.Errors.Count > 0)
        .ToDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value!.Errors
                .Select(e => e.ErrorMessage)
                .ToArray()
        );

    return new ApiErrorResponse
    {
        Status = StatusCodes.Status400BadRequest,
        Title = "Validation failed",
        Detail = "One or more fields contain invalid values.",
        Errors = errors,
        CorrelationId = context.HttpContext.TraceIdentifier
    };
}
